window.MG_LAZY_DATA["data/lazy/courses/v11-majorana-parity-b36462f9d2e63338.json"]={sha256:"b36462f9d2e63338ed8a37207c660f4bac0e9f3931a7f6bf0958f657ad3bfb36",value:{"id":"v11-majorana-parity","title":"Majorana 1 研發與奇偶量測證據","titleEn":"Majorana 1 research and parity-measurement evidence","category":"computing","subcategory":"quantum-topological","subcategoryTitle":"拓撲量子研究與證據","subcategoryTitleEn":"Topological quantum research and evidence","learningTrack":"quantum","learningSubdiscipline":"quantum-topological","learningTags":["quantum","quantum-topological","majorana-parity"],"kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"curriculumVersion":11,"stepCount":12,"estimatedMinutes":420,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"sourceIds":["v11x-parity","v11x-majoranaclaim"],"stages":[{"id":"v11-majorana-parity-v11-stage1","order":1,"title":"系統邊界與基本原理","titleEn":"System boundaries and principles","description":"在Majorana 1 研發與奇偶量測證據案例中比較InAs–Al近接結構與電容與奇偶干涉，各完成分析及驗證。","descriptionEn":"Analyze and validate inas-al proximity structures and capacitance and parity interference within the Majorana 1 research and parity-measurement evidence case.","steps":[{"id":"v11-majorana-parity-v11-01","order":1,"sequence":1,"title":"近接材料與能隙：架構分析","titleEn":"Proximity materials and gaps: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-parity","v11x-majoranaclaim"],"prerequisiteIds":[],"objective":"針對InAs–Al近接結構提出可反駁的近接材料與能隙模型與驗證紀錄。","objectiveEn":"Produce a falsifiable proximity materials and gaps model and evidence record for inas-al proximity structures.","instruction":"在「Majorana 1 研發與奇偶量測證據」的師傅示意與公開來源中，先辨識InAs–Al近接結構。半導體與超導體的近接結構可能產生不同低能態；材料設計本身不是拓撲證據。 建立近接材料與能隙的輸入、狀態、輸出及邊界圖；本課重點是近接材料、奇偶讀出及拓撲宣稱審查。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。列出拓撲與平庸模型都能解釋的觀測。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify inas-al proximity structures in the mentor diagram and primary sources for Majorana 1 research and parity-measurement evidence. Proximity heterostructures can host different low-energy states; material design alone is not topological evidence. Draw the inputs, states, outputs and boundaries of proximity materials and gaps, focusing on proximity materials, parity readout and review of topological claims. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. List observations compatible with both topological and trivial models. Record units, undisclosed parameters and model breakdown conditions.","observation":"列出拓撲與平庸模型都能解釋的觀測。","observationEn":"List observations compatible with both topological and trivial models.","failure":"常見誤判：使用特定材料就已證明 Majorana 零模。","failureEn":"Common misconception: A particular material proves Majorana zero modes.","check":"提交InAs–Al近接結構的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for inas-al proximity structures.","knowledge":[{"id":"v11-majorana-parity-v11-01-k1","title":"近接材料與能隙","titleEn":"Proximity materials and gaps","text":"半導體與超導體的近接結構可能產生不同低能態；材料設計本身不是拓撲證據。 本課架構對應：InAs–Al近接結構","textEn":"Proximity heterostructures can host different low-energy states; material design alone is not topological evidence. Course architecture correspondence: InAs-Al proximity structures","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-01-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"列出拓撲與平庸模型都能解釋的觀測。 應逐項保留基準與不確定度；使用特定材料就已證明 Majorana 零模。 是本單元要排除的誤解。","textEn":"List observations compatible with both topological and trivial models. Retain each reference and uncertainty; reject the misconception: A particular material proves Majorana zero modes.","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-01-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假想讀出1000次，兩標籤各500次，錯分各5次與10次：兩類錯分率1%與2%，均衡錯分率1.5%。這只能量化該假想讀出，不能證明拓撲性、非阿貝爾操作或受保護邏輯位元。","textEn":"Assume 1000 readouts with 500 per label and 5/10 misassignments: class errors 1%/2%, balanced error 1.5%. This quantifies assumed readout only, not topology, non-Abelian operations or protected logical qubits.","sourceIds":["v11x-parity","v11x-majoranaclaim"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就InAs–Al近接結構的「近接材料與能隙」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for proximity materials and gaps in inas-al proximity structures?","options":["半導體與超導體的近接結構可能產生不同低能態；材料設計本身不是拓撲證據。","使用特定材料就已證明 Majorana 零模。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Proximity heterostructures can host different low-energy states; material design alone is not topological evidence.","A particular material proves Majorana zero modes.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"半導體與超導體的近接結構可能產生不同低能態；材料設計本身不是拓撲證據。 列出拓撲與平庸模型都能解釋的觀測。","explanationEn":"Proximity heterostructures can host different low-energy states; material design alone is not topological evidence. List observations compatible with both topological and trivial models."}},{"id":"v11-majorana-parity-v11-02","order":2,"sequence":2,"title":"近接材料與能隙：證據驗證","titleEn":"Proximity materials and gaps: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-parity","v11x-majoranaclaim"],"prerequisiteIds":["v11-majorana-parity-v11-01"],"objective":"針對InAs–Al近接結構提出可反駁的近接材料與能隙模型與驗證紀錄。","objectiveEn":"Produce a falsifiable proximity materials and gaps model and evidence record for inas-al proximity structures.","instruction":"沿用前一步「近接材料與能隙」模型，檢查InAs–Al近接結構的兩個假想案例。列出拓撲與平庸模型都能解釋的觀測。 先訂可接受誤差，再比較預測與獨立計算；區分半導體與超導體的近接結構可能產生不同低能態；材料設計本身不是拓撲證據。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous proximity materials and gaps model to inspect two hypothetical cases involving inas-al proximity structures. List observations compatible with both topological and trivial models. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Proximity heterostructures can host different low-energy states; material design alone is not topological evidence.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"列出拓撲與平庸模型都能解釋的觀測。","observationEn":"List observations compatible with both topological and trivial models.","failure":"常見誤判：使用特定材料就已證明 Majorana 零模。","failureEn":"Common misconception: A particular material proves Majorana zero modes.","check":"提交InAs–Al近接結構的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for inas-al proximity structures.","knowledge":[{"id":"v11-majorana-parity-v11-02-k1","title":"近接材料與能隙","titleEn":"Proximity materials and gaps","text":"半導體與超導體的近接結構可能產生不同低能態；材料設計本身不是拓撲證據。 本課架構對應：InAs–Al近接結構","textEn":"Proximity heterostructures can host different low-energy states; material design alone is not topological evidence. Course architecture correspondence: InAs-Al proximity structures","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-02-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"列出拓撲與平庸模型都能解釋的觀測。 應逐項保留基準與不確定度；使用特定材料就已證明 Majorana 零模。 是本單元要排除的誤解。","textEn":"List observations compatible with both topological and trivial models. Retain each reference and uncertainty; reject the misconception: A particular material proves Majorana zero modes.","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-02-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假想讀出1000次，兩標籤各500次，錯分各5次與10次：兩類錯分率1%與2%，均衡錯分率1.5%。這只能量化該假想讀出，不能證明拓撲性、非阿貝爾操作或受保護邏輯位元。","textEn":"Assume 1000 readouts with 500 per label and 5/10 misassignments: class errors 1%/2%, balanced error 1.5%. This quantifies assumed readout only, not topology, non-Abelian operations or protected logical qubits.","sourceIds":["v11x-parity","v11x-majoranaclaim"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就InAs–Al近接結構的「近接材料與能隙」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for proximity materials and gaps in inas-al proximity structures?","options":["使用特定材料就已證明 Majorana 零模。","列出拓撲與平庸模型都能解釋的觀測。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["A particular material proves Majorana zero modes.","List observations compatible with both topological and trivial models.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"半導體與超導體的近接結構可能產生不同低能態；材料設計本身不是拓撲證據。 列出拓撲與平庸模型都能解釋的觀測。","explanationEn":"Proximity heterostructures can host different low-energy states; material design alone is not topological evidence. List observations compatible with both topological and trivial models."}},{"id":"v11-majorana-parity-v11-03","order":3,"sequence":3,"title":"奇偶量測架構：架構分析","titleEn":"Parity-measurement architecture: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-parity","v11x-majoranaclaim"],"prerequisiteIds":["v11-majorana-parity-v11-02"],"objective":"針對電容與奇偶干涉提出可反駁的奇偶量測架構模型與驗證紀錄。","objectiveEn":"Produce a falsifiable parity-measurement architecture model and evidence record for capacitance and parity interference.","instruction":"在「Majorana 1 研發與奇偶量測證據」的師傅示意與公開來源中，先辨識電容與奇偶干涉。奇偶資訊與單個電荷事件不同；干涉及電容量測需明確指定可觀測量。 建立奇偶量測架構的輸入、狀態、輸出及邊界圖；本課重點是近接材料、奇偶讀出及拓撲宣稱審查。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。畫裝置—訊號—推論三層證據圖。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify capacitance and parity interference in the mentor diagram and primary sources for Majorana 1 research and parity-measurement evidence. Parity differs from individual charge events; interferometric/capacitance readout must specify observables. Draw the inputs, states, outputs and boundaries of parity-measurement architecture, focusing on proximity materials, parity readout and review of topological claims. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Draw device, signal and inference as separate evidence layers. Record units, undisclosed parameters and model breakdown conditions.","observation":"畫裝置—訊號—推論三層證據圖。","observationEn":"Draw device, signal and inference as separate evidence layers.","failure":"常見誤判：奇偶量測單獨證明所有拓撲運算。","failureEn":"Common misconception: Parity measurement alone proves every topological operation.","check":"提交電容與奇偶干涉的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for capacitance and parity interference.","knowledge":[{"id":"v11-majorana-parity-v11-03-k1","title":"奇偶量測架構","titleEn":"Parity-measurement architecture","text":"奇偶資訊與單個電荷事件不同；干涉及電容量測需明確指定可觀測量。 本課架構對應：電容與奇偶干涉","textEn":"Parity differs from individual charge events; interferometric/capacitance readout must specify observables. Course architecture correspondence: Capacitance and parity interference","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-03-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"畫裝置—訊號—推論三層證據圖。 應逐項保留基準與不確定度；奇偶量測單獨證明所有拓撲運算。 是本單元要排除的誤解。","textEn":"Draw device, signal and inference as separate evidence layers. Retain each reference and uncertainty; reject the misconception: Parity measurement alone proves every topological operation.","sourceIds":["v11x-parity","v11x-majoranaclaim"]}],"quiz":{"question":"就電容與奇偶干涉的「奇偶量測架構」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for parity-measurement architecture in capacitance and parity interference?","options":["奇偶量測單獨證明所有拓撲運算。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","奇偶資訊與單個電荷事件不同；干涉及電容量測需明確指定可觀測量。"],"optionsEn":["Parity measurement alone proves every topological operation.","Equal case averages rule out spatial, temporal and model errors.","Parity differs from individual charge events; interferometric/capacitance readout must specify observables."],"answer":2,"explanation":"奇偶資訊與單個電荷事件不同；干涉及電容量測需明確指定可觀測量。 畫裝置—訊號—推論三層證據圖。","explanationEn":"Parity differs from individual charge events; interferometric/capacitance readout must specify observables. Draw device, signal and inference as separate evidence layers."}},{"id":"v11-majorana-parity-v11-04","order":4,"sequence":4,"title":"奇偶量測架構：證據驗證","titleEn":"Parity-measurement architecture: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-parity","v11x-majoranaclaim"],"prerequisiteIds":["v11-majorana-parity-v11-03"],"objective":"針對電容與奇偶干涉提出可反駁的奇偶量測架構模型與驗證紀錄。","objectiveEn":"Produce a falsifiable parity-measurement architecture model and evidence record for capacitance and parity interference.","instruction":"沿用前一步「奇偶量測架構」模型，檢查電容與奇偶干涉的兩個假想案例。畫裝置—訊號—推論三層證據圖。 先訂可接受誤差，再比較預測與獨立計算；區分奇偶資訊與單個電荷事件不同；干涉及電容量測需明確指定可觀測量。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous parity-measurement architecture model to inspect two hypothetical cases involving capacitance and parity interference. Draw device, signal and inference as separate evidence layers. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Parity differs from individual charge events; interferometric/capacitance readout must specify observables.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"畫裝置—訊號—推論三層證據圖。","observationEn":"Draw device, signal and inference as separate evidence layers.","failure":"常見誤判：奇偶量測單獨證明所有拓撲運算。","failureEn":"Common misconception: Parity measurement alone proves every topological operation.","check":"提交電容與奇偶干涉的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for capacitance and parity interference.","knowledge":[{"id":"v11-majorana-parity-v11-04-k1","title":"奇偶量測架構","titleEn":"Parity-measurement architecture","text":"奇偶資訊與單個電荷事件不同；干涉及電容量測需明確指定可觀測量。 本課架構對應：電容與奇偶干涉","textEn":"Parity differs from individual charge events; interferometric/capacitance readout must specify observables. Course architecture correspondence: Capacitance and parity interference","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-04-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"畫裝置—訊號—推論三層證據圖。 應逐項保留基準與不確定度；奇偶量測單獨證明所有拓撲運算。 是本單元要排除的誤解。","textEn":"Draw device, signal and inference as separate evidence layers. Retain each reference and uncertainty; reject the misconception: Parity measurement alone proves every topological operation.","sourceIds":["v11x-parity","v11x-majoranaclaim"]}],"quiz":{"question":"就電容與奇偶干涉的「奇偶量測架構」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for parity-measurement architecture in capacitance and parity interference?","options":["畫裝置—訊號—推論三層證據圖。","奇偶量測單獨證明所有拓撲運算。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Draw device, signal and inference as separate evidence layers.","Parity measurement alone proves every topological operation.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"奇偶資訊與單個電荷事件不同；干涉及電容量測需明確指定可觀測量。 畫裝置—訊號—推論三層證據圖。","explanationEn":"Parity differs from individual charge events; interferometric/capacitance readout must specify observables. Draw device, signal and inference as separate evidence layers."}}]},{"id":"v11-majorana-parity-v11-stage2","order":2,"title":"功能架構與量化模型","titleEn":"Functional architecture and quantitative models","description":"在Majorana 1 研發與奇偶量測證據案例中比較指派分佈與平庸態競爭假說，各完成分析及驗證。","descriptionEn":"Analyze and validate assignment distributions and trivial-state competing hypotheses within the Majorana 1 research and parity-measurement evidence case.","steps":[{"id":"v11-majorana-parity-v11-05","order":1,"sequence":5,"title":"信噪比與指派：架構分析","titleEn":"SNR and assignment: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-parity","v11x-majoranaclaim"],"prerequisiteIds":["v11-majorana-parity-v11-04"],"objective":"針對指派分佈提出可反駁的信噪比與指派模型與驗證紀錄。","objectiveEn":"Produce a falsifiable snr and assignment model and evidence record for assignment distributions.","instruction":"在「Majorana 1 研發與奇偶量測證據」的師傅示意與公開來源中，先辨識指派分佈。讀出指派錯誤取決於分佈重疊與時間窗；信噪比不是邏輯位元精度。 建立信噪比與指派的輸入、狀態、輸出及邊界圖；本課重點是近接材料、奇偶讀出及拓撲宣稱審查。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。用假想分佈重算信噪比及錯誤率。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify assignment distributions in the mentor diagram and primary sources for Majorana 1 research and parity-measurement evidence. Assignment error depends on distribution overlap/window; SNR is not logical-qubit fidelity. Draw the inputs, states, outputs and boundaries of snr and assignment, focusing on proximity materials, parity readout and review of topological claims. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Recompute SNR and error for assumed distributions. Record units, undisclosed parameters and model breakdown conditions.","observation":"用假想分佈重算信噪比及錯誤率。","observationEn":"Recompute SNR and error for assumed distributions.","failure":"常見誤判：一次高信噪比代表容錯閘已完成。","failureEn":"Common misconception: One high-SNR readout establishes fault-tolerant gates.","check":"提交指派分佈的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for assignment distributions.","knowledge":[{"id":"v11-majorana-parity-v11-05-k1","title":"信噪比與指派","titleEn":"SNR and assignment","text":"讀出指派錯誤取決於分佈重疊與時間窗；信噪比不是邏輯位元精度。 本課架構對應：指派分佈","textEn":"Assignment error depends on distribution overlap/window; SNR is not logical-qubit fidelity. Course architecture correspondence: Assignment distributions","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-05-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"用假想分佈重算信噪比及錯誤率。 應逐項保留基準與不確定度；一次高信噪比代表容錯閘已完成。 是本單元要排除的誤解。","textEn":"Recompute SNR and error for assumed distributions. Retain each reference and uncertainty; reject the misconception: One high-SNR readout establishes fault-tolerant gates.","sourceIds":["v11x-parity","v11x-majoranaclaim"]}],"quiz":{"question":"就指派分佈的「信噪比與指派」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for snr and assignment in assignment distributions?","options":["一次高信噪比代表容錯閘已完成。","讀出指派錯誤取決於分佈重疊與時間窗；信噪比不是邏輯位元精度。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["One high-SNR readout establishes fault-tolerant gates.","Assignment error depends on distribution overlap/window; SNR is not logical-qubit fidelity.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"讀出指派錯誤取決於分佈重疊與時間窗；信噪比不是邏輯位元精度。 用假想分佈重算信噪比及錯誤率。","explanationEn":"Assignment error depends on distribution overlap/window; SNR is not logical-qubit fidelity. Recompute SNR and error for assumed distributions."}},{"id":"v11-majorana-parity-v11-06","order":2,"sequence":6,"title":"信噪比與指派：證據驗證","titleEn":"SNR and assignment: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-parity","v11x-majoranaclaim"],"prerequisiteIds":["v11-majorana-parity-v11-05"],"objective":"針對指派分佈提出可反駁的信噪比與指派模型與驗證紀錄。","objectiveEn":"Produce a falsifiable snr and assignment model and evidence record for assignment distributions.","instruction":"沿用前一步「信噪比與指派」模型，檢查指派分佈的兩個假想案例。用假想分佈重算信噪比及錯誤率。 先訂可接受誤差，再比較預測與獨立計算；區分讀出指派錯誤取決於分佈重疊與時間窗；信噪比不是邏輯位元精度。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous snr and assignment model to inspect two hypothetical cases involving assignment distributions. Recompute SNR and error for assumed distributions. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Assignment error depends on distribution overlap/window; SNR is not logical-qubit fidelity.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"用假想分佈重算信噪比及錯誤率。","observationEn":"Recompute SNR and error for assumed distributions.","failure":"常見誤判：一次高信噪比代表容錯閘已完成。","failureEn":"Common misconception: One high-SNR readout establishes fault-tolerant gates.","check":"提交指派分佈的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for assignment distributions.","knowledge":[{"id":"v11-majorana-parity-v11-06-k1","title":"信噪比與指派","titleEn":"SNR and assignment","text":"讀出指派錯誤取決於分佈重疊與時間窗；信噪比不是邏輯位元精度。 本課架構對應：指派分佈","textEn":"Assignment error depends on distribution overlap/window; SNR is not logical-qubit fidelity. Course architecture correspondence: Assignment distributions","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-06-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"用假想分佈重算信噪比及錯誤率。 應逐項保留基準與不確定度；一次高信噪比代表容錯閘已完成。 是本單元要排除的誤解。","textEn":"Recompute SNR and error for assumed distributions. Retain each reference and uncertainty; reject the misconception: One high-SNR readout establishes fault-tolerant gates.","sourceIds":["v11x-parity","v11x-majoranaclaim"]}],"quiz":{"question":"就指派分佈的「信噪比與指派」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for snr and assignment in assignment distributions?","options":["一次高信噪比代表容錯閘已完成。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","用假想分佈重算信噪比及錯誤率。"],"optionsEn":["One high-SNR readout establishes fault-tolerant gates.","Equal case averages rule out spatial, temporal and model errors.","Recompute SNR and error for assumed distributions."],"answer":2,"explanation":"讀出指派錯誤取決於分佈重疊與時間窗；信噪比不是邏輯位元精度。 用假想分佈重算信噪比及錯誤率。","explanationEn":"Assignment error depends on distribution overlap/window; SNR is not logical-qubit fidelity. Recompute SNR and error for assumed distributions."}},{"id":"v11-majorana-parity-v11-07","order":3,"sequence":7,"title":"平庸態的競爭假說：架構分析","titleEn":"Competing trivial-state hypotheses: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-parity","v11x-majoranaclaim"],"prerequisiteIds":["v11-majorana-parity-v11-06"],"objective":"針對平庸態競爭假說提出可反駁的平庸態的競爭假說模型與驗證紀錄。","objectiveEn":"Produce a falsifiable competing trivial-state hypotheses model and evidence record for trivial-state competing hypotheses.","instruction":"在「Majorana 1 研發與奇偶量測證據」的師傅示意與公開來源中，先辨識平庸態競爭假說。替代機制也可能產生低能訊號；區分它們需要多個獨立觀測與模型。 建立平庸態的競爭假說的輸入、狀態、輸出及邊界圖；本課重點是近接材料、奇偶讀出及拓撲宣稱審查。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。為至少兩個假說挑選預測不同的量測。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify trivial-state competing hypotheses in the mentor diagram and primary sources for Majorana 1 research and parity-measurement evidence. Alternative mechanisms can produce low-energy signals; discrimination needs independent observables and models. Draw the inputs, states, outputs and boundaries of competing trivial-state hypotheses, focusing on proximity materials, parity readout and review of topological claims. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Choose measurements with different predictions for two hypotheses. Record units, undisclosed parameters and model breakdown conditions.","observation":"為至少兩個假說挑選預測不同的量測。","observationEn":"Choose measurements with different predictions for two hypotheses.","failure":"常見誤判：來源標題中的產品名稱可以取代物理證據。","failureEn":"Common misconception: A product name in a headline replaces physical evidence.","check":"提交平庸態競爭假說的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for trivial-state competing hypotheses.","knowledge":[{"id":"v11-majorana-parity-v11-07-k1","title":"平庸態的競爭假說","titleEn":"Competing trivial-state hypotheses","text":"替代機制也可能產生低能訊號；區分它們需要多個獨立觀測與模型。 本課架構對應：平庸態競爭假說","textEn":"Alternative mechanisms can produce low-energy signals; discrimination needs independent observables and models. Course architecture correspondence: Trivial-state competing hypotheses","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-07-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"為至少兩個假說挑選預測不同的量測。 應逐項保留基準與不確定度；來源標題中的產品名稱可以取代物理證據。 是本單元要排除的誤解。","textEn":"Choose measurements with different predictions for two hypotheses. Retain each reference and uncertainty; reject the misconception: A product name in a headline replaces physical evidence.","sourceIds":["v11x-parity","v11x-majoranaclaim"]}],"quiz":{"question":"就平庸態競爭假說的「平庸態的競爭假說」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for competing trivial-state hypotheses in trivial-state competing hypotheses?","options":["替代機制也可能產生低能訊號；區分它們需要多個獨立觀測與模型。","來源標題中的產品名稱可以取代物理證據。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Alternative mechanisms can produce low-energy signals; discrimination needs independent observables and models.","A product name in a headline replaces physical evidence.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"替代機制也可能產生低能訊號；區分它們需要多個獨立觀測與模型。 為至少兩個假說挑選預測不同的量測。","explanationEn":"Alternative mechanisms can produce low-energy signals; discrimination needs independent observables and models. Choose measurements with different predictions for two hypotheses."}},{"id":"v11-majorana-parity-v11-08","order":4,"sequence":8,"title":"平庸態的競爭假說：證據驗證","titleEn":"Competing trivial-state hypotheses: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-parity","v11x-majoranaclaim"],"prerequisiteIds":["v11-majorana-parity-v11-07"],"objective":"針對平庸態競爭假說提出可反駁的平庸態的競爭假說模型與驗證紀錄。","objectiveEn":"Produce a falsifiable competing trivial-state hypotheses model and evidence record for trivial-state competing hypotheses.","instruction":"沿用前一步「平庸態的競爭假說」模型，檢查平庸態競爭假說的兩個假想案例。為至少兩個假說挑選預測不同的量測。 先訂可接受誤差，再比較預測與獨立計算；區分替代機制也可能產生低能訊號；區分它們需要多個獨立觀測與模型。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous competing trivial-state hypotheses model to inspect two hypothetical cases involving trivial-state competing hypotheses. Choose measurements with different predictions for two hypotheses. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Alternative mechanisms can produce low-energy signals; discrimination needs independent observables and models.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"為至少兩個假說挑選預測不同的量測。","observationEn":"Choose measurements with different predictions for two hypotheses.","failure":"常見誤判：來源標題中的產品名稱可以取代物理證據。","failureEn":"Common misconception: A product name in a headline replaces physical evidence.","check":"提交平庸態競爭假說的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for trivial-state competing hypotheses.","knowledge":[{"id":"v11-majorana-parity-v11-08-k1","title":"平庸態的競爭假說","titleEn":"Competing trivial-state hypotheses","text":"替代機制也可能產生低能訊號；區分它們需要多個獨立觀測與模型。 本課架構對應：平庸態競爭假說","textEn":"Alternative mechanisms can produce low-energy signals; discrimination needs independent observables and models. Course architecture correspondence: Trivial-state competing hypotheses","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-08-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"為至少兩個假說挑選預測不同的量測。 應逐項保留基準與不確定度；來源標題中的產品名稱可以取代物理證據。 是本單元要排除的誤解。","textEn":"Choose measurements with different predictions for two hypotheses. Retain each reference and uncertainty; reject the misconception: A product name in a headline replaces physical evidence.","sourceIds":["v11x-parity","v11x-majoranaclaim"]}],"quiz":{"question":"就平庸態競爭假說的「平庸態的競爭假說」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for competing trivial-state hypotheses in trivial-state competing hypotheses?","options":["來源標題中的產品名稱可以取代物理證據。","為至少兩個假說挑選預測不同的量測。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["A product name in a headline replaces physical evidence.","Choose measurements with different predictions for two hypotheses.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"替代機制也可能產生低能訊號；區分它們需要多個獨立觀測與模型。 為至少兩個假說挑選預測不同的量測。","explanationEn":"Alternative mechanisms can produce low-energy signals; discrimination needs independent observables and models. Choose measurements with different predictions for two hypotheses."}}]},{"id":"v11-majorana-parity-v11-stage3","order":3,"title":"獨立驗證與工程交接","titleEn":"Independent validation and engineering handoff","description":"在Majorana 1 研發與奇偶量測證據案例中比較受保護操作證據與論文與路線圖邊界，各完成分析及驗證。","descriptionEn":"Analyze and validate protected-operation evidence and paper/roadmap boundaries within the Majorana 1 research and parity-measurement evidence case.","steps":[{"id":"v11-majorana-parity-v11-09","order":1,"sequence":9,"title":"保護與操作證據：架構分析","titleEn":"Protection and operation evidence: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-parity","v11x-majoranaclaim"],"prerequisiteIds":["v11-majorana-parity-v11-08"],"objective":"針對受保護操作證據提出可反駁的保護與操作證據模型與驗證紀錄。","objectiveEn":"Produce a falsifiable protection and operation evidence model and evidence record for protected-operation evidence.","instruction":"在「Majorana 1 研發與奇偶量測證據」的師傅示意與公開來源中，先辨識受保護操作證據。聲稱受保護位元需證明編碼、操作與噪聲響應；裝置量測與完整邏輯運算不同。 建立保護與操作證據的輸入、狀態、輸出及邊界圖；本課重點是近接材料、奇偶讀出及拓撲宣稱審查。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。分開已公開演示、作者推論與未證實能力。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify protected-operation evidence in the mentor diagram and primary sources for Majorana 1 research and parity-measurement evidence. A protected-qubit claim needs encoding, operations and noise response; a device measurement differs from full logical computation. Draw the inputs, states, outputs and boundaries of protection and operation evidence, focusing on proximity materials, parity readout and review of topological claims. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Separate public demonstrations, inferred claims and unverified capabilities. Record units, undisclosed parameters and model breakdown conditions.","observation":"分開已公開演示、作者推論與未證實能力。","observationEn":"Separate public demonstrations, inferred claims and unverified capabilities.","failure":"常見誤判：可縮放路線圖就是實現百萬容錯位元的證明。","failureEn":"Common misconception: A scaling roadmap proves a million fault-tolerant qubits.","check":"提交受保護操作證據的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for protected-operation evidence.","knowledge":[{"id":"v11-majorana-parity-v11-09-k1","title":"保護與操作證據","titleEn":"Protection and operation evidence","text":"聲稱受保護位元需證明編碼、操作與噪聲響應；裝置量測與完整邏輯運算不同。 本課架構對應：受保護操作證據","textEn":"A protected-qubit claim needs encoding, operations and noise response; a device measurement differs from full logical computation. Course architecture correspondence: Protected-operation evidence","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-09-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"分開已公開演示、作者推論與未證實能力。 應逐項保留基準與不確定度；可縮放路線圖就是實現百萬容錯位元的證明。 是本單元要排除的誤解。","textEn":"Separate public demonstrations, inferred claims and unverified capabilities. Retain each reference and uncertainty; reject the misconception: A scaling roadmap proves a million fault-tolerant qubits.","sourceIds":["v11x-parity","v11x-majoranaclaim"]}],"quiz":{"question":"就受保護操作證據的「保護與操作證據」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for protection and operation evidence in protected-operation evidence?","options":["可縮放路線圖就是實現百萬容錯位元的證明。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","聲稱受保護位元需證明編碼、操作與噪聲響應；裝置量測與完整邏輯運算不同。"],"optionsEn":["A scaling roadmap proves a million fault-tolerant qubits.","Equal case averages rule out spatial, temporal and model errors.","A protected-qubit claim needs encoding, operations and noise response; a device measurement differs from full logical computation."],"answer":2,"explanation":"聲稱受保護位元需證明編碼、操作與噪聲響應；裝置量測與完整邏輯運算不同。 分開已公開演示、作者推論與未證實能力。","explanationEn":"A protected-qubit claim needs encoding, operations and noise response; a device measurement differs from full logical computation. Separate public demonstrations, inferred claims and unverified capabilities."}},{"id":"v11-majorana-parity-v11-10","order":2,"sequence":10,"title":"保護與操作證據：證據驗證","titleEn":"Protection and operation evidence: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-parity","v11x-majoranaclaim"],"prerequisiteIds":["v11-majorana-parity-v11-09"],"objective":"針對受保護操作證據提出可反駁的保護與操作證據模型與驗證紀錄。","objectiveEn":"Produce a falsifiable protection and operation evidence model and evidence record for protected-operation evidence.","instruction":"沿用前一步「保護與操作證據」模型，檢查受保護操作證據的兩個假想案例。分開已公開演示、作者推論與未證實能力。 先訂可接受誤差，再比較預測與獨立計算；區分聲稱受保護位元需證明編碼、操作與噪聲響應；裝置量測與完整邏輯運算不同。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous protection and operation evidence model to inspect two hypothetical cases involving protected-operation evidence. Separate public demonstrations, inferred claims and unverified capabilities. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"A protected-qubit claim needs encoding, operations and noise response; a device measurement differs from full logical computation.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"分開已公開演示、作者推論與未證實能力。","observationEn":"Separate public demonstrations, inferred claims and unverified capabilities.","failure":"常見誤判：可縮放路線圖就是實現百萬容錯位元的證明。","failureEn":"Common misconception: A scaling roadmap proves a million fault-tolerant qubits.","check":"提交受保護操作證據的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for protected-operation evidence.","knowledge":[{"id":"v11-majorana-parity-v11-10-k1","title":"保護與操作證據","titleEn":"Protection and operation evidence","text":"聲稱受保護位元需證明編碼、操作與噪聲響應；裝置量測與完整邏輯運算不同。 本課架構對應：受保護操作證據","textEn":"A protected-qubit claim needs encoding, operations and noise response; a device measurement differs from full logical computation. Course architecture correspondence: Protected-operation evidence","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-10-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"分開已公開演示、作者推論與未證實能力。 應逐項保留基準與不確定度；可縮放路線圖就是實現百萬容錯位元的證明。 是本單元要排除的誤解。","textEn":"Separate public demonstrations, inferred claims and unverified capabilities. Retain each reference and uncertainty; reject the misconception: A scaling roadmap proves a million fault-tolerant qubits.","sourceIds":["v11x-parity","v11x-majoranaclaim"]}],"quiz":{"question":"就受保護操作證據的「保護與操作證據」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for protection and operation evidence in protected-operation evidence?","options":["分開已公開演示、作者推論與未證實能力。","可縮放路線圖就是實現百萬容錯位元的證明。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Separate public demonstrations, inferred claims and unverified capabilities.","A scaling roadmap proves a million fault-tolerant qubits.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"聲稱受保護位元需證明編碼、操作與噪聲響應；裝置量測與完整邏輯運算不同。 分開已公開演示、作者推論與未證實能力。","explanationEn":"A protected-qubit claim needs encoding, operations and noise response; a device measurement differs from full logical computation. Separate public demonstrations, inferred claims and unverified capabilities."}},{"id":"v11-majorana-parity-v11-11","order":3,"sequence":11,"title":"研究重現與版本：架構分析","titleEn":"Research reproducibility and revisions: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-parity","v11x-majoranaclaim"],"prerequisiteIds":["v11-majorana-parity-v11-10"],"objective":"針對論文與路線圖邊界提出可反駁的研究重現與版本模型與驗證紀錄。","objectiveEn":"Produce a falsifiable research reproducibility and revisions model and evidence record for paper/roadmap boundaries.","instruction":"在「Majorana 1 研發與奇偶量測證據」的師傅示意與公開來源中，先辨識論文與路線圖邊界。原始論文的適用範圍可能小於公司路線圖；應保存版本、數據與推論限制。 建立研究重現與版本的輸入、狀態、輸出及邊界圖；本課重點是近接材料、奇偶讀出及拓撲宣稱審查。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。並排比較論文摘要與商業宣稱所需新增證據。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify paper/roadmap boundaries in the mentor diagram and primary sources for Majorana 1 research and parity-measurement evidence. A paper may support narrower claims than a roadmap; retain versions, data and inference limitations. Draw the inputs, states, outputs and boundaries of research reproducibility and revisions, focusing on proximity materials, parity readout and review of topological claims. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare paper-supported claims with evidence still required for commercial claims. Record units, undisclosed parameters and model breakdown conditions.","observation":"並排比較論文摘要與商業宣稱所需新增證據。","observationEn":"Compare paper-supported claims with evidence still required for commercial claims.","failure":"常見誤判：論文與產品宣稱的適用範圍必然相同。","failureEn":"Common misconception: A paper and product announcement necessarily support identical scope.","check":"提交論文與路線圖邊界的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for paper/roadmap boundaries.","knowledge":[{"id":"v11-majorana-parity-v11-11-k1","title":"研究重現與版本","titleEn":"Research reproducibility and revisions","text":"原始論文的適用範圍可能小於公司路線圖；應保存版本、數據與推論限制。 本課架構對應：論文與路線圖邊界","textEn":"A paper may support narrower claims than a roadmap; retain versions, data and inference limitations. Course architecture correspondence: Paper/roadmap boundaries","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-11-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"並排比較論文摘要與商業宣稱所需新增證據。 應逐項保留基準與不確定度；論文與產品宣稱的適用範圍必然相同。 是本單元要排除的誤解。","textEn":"Compare paper-supported claims with evidence still required for commercial claims. Retain each reference and uncertainty; reject the misconception: A paper and product announcement necessarily support identical scope.","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-11-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假想讀出1000次，兩標籤各500次，錯分各5次與10次：兩類錯分率1%與2%，均衡錯分率1.5%。這只能量化該假想讀出，不能證明拓撲性、非阿貝爾操作或受保護邏輯位元。","textEn":"Assume 1000 readouts with 500 per label and 5/10 misassignments: class errors 1%/2%, balanced error 1.5%. This quantifies assumed readout only, not topology, non-Abelian operations or protected logical qubits.","sourceIds":["v11x-parity","v11x-majoranaclaim"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就論文與路線圖邊界的「研究重現與版本」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for research reproducibility and revisions in paper/roadmap boundaries?","options":["論文與產品宣稱的適用範圍必然相同。","原始論文的適用範圍可能小於公司路線圖；應保存版本、數據與推論限制。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["A paper and product announcement necessarily support identical scope.","A paper may support narrower claims than a roadmap; retain versions, data and inference limitations.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"原始論文的適用範圍可能小於公司路線圖；應保存版本、數據與推論限制。 並排比較論文摘要與商業宣稱所需新增證據。","explanationEn":"A paper may support narrower claims than a roadmap; retain versions, data and inference limitations. Compare paper-supported claims with evidence still required for commercial claims."}},{"id":"v11-majorana-parity-v11-12","order":4,"sequence":12,"title":"研究重現與版本：證據驗證","titleEn":"Research reproducibility and revisions: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-parity","v11x-majoranaclaim"],"prerequisiteIds":["v11-majorana-parity-v11-11"],"objective":"針對論文與路線圖邊界提出可反駁的研究重現與版本模型與驗證紀錄。","objectiveEn":"Produce a falsifiable research reproducibility and revisions model and evidence record for paper/roadmap boundaries.","instruction":"沿用前一步「研究重現與版本」模型，檢查論文與路線圖邊界的兩個假想案例。並排比較論文摘要與商業宣稱所需新增證據。 先訂可接受誤差，再比較預測與獨立計算；區分原始論文的適用範圍可能小於公司路線圖；應保存版本、數據與推論限制。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous research reproducibility and revisions model to inspect two hypothetical cases involving paper/roadmap boundaries. Compare paper-supported claims with evidence still required for commercial claims. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"A paper may support narrower claims than a roadmap; retain versions, data and inference limitations.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"並排比較論文摘要與商業宣稱所需新增證據。","observationEn":"Compare paper-supported claims with evidence still required for commercial claims.","failure":"常見誤判：論文與產品宣稱的適用範圍必然相同。","failureEn":"Common misconception: A paper and product announcement necessarily support identical scope.","check":"提交論文與路線圖邊界的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for paper/roadmap boundaries.","knowledge":[{"id":"v11-majorana-parity-v11-12-k1","title":"研究重現與版本","titleEn":"Research reproducibility and revisions","text":"原始論文的適用範圍可能小於公司路線圖；應保存版本、數據與推論限制。 本課架構對應：論文與路線圖邊界","textEn":"A paper may support narrower claims than a roadmap; retain versions, data and inference limitations. Course architecture correspondence: Paper/roadmap boundaries","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-12-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"並排比較論文摘要與商業宣稱所需新增證據。 應逐項保留基準與不確定度；論文與產品宣稱的適用範圍必然相同。 是本單元要排除的誤解。","textEn":"Compare paper-supported claims with evidence still required for commercial claims. Retain each reference and uncertainty; reject the misconception: A paper and product announcement necessarily support identical scope.","sourceIds":["v11x-parity","v11x-majoranaclaim"]},{"id":"v11-majorana-parity-v11-12-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假想讀出1000次，兩標籤各500次，錯分各5次與10次：兩類錯分率1%與2%，均衡錯分率1.5%。這只能量化該假想讀出，不能證明拓撲性、非阿貝爾操作或受保護邏輯位元。","textEn":"Assume 1000 readouts with 500 per label and 5/10 misassignments: class errors 1%/2%, balanced error 1.5%. This quantifies assumed readout only, not topology, non-Abelian operations or protected logical qubits.","sourceIds":["v11x-parity","v11x-majoranaclaim"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就論文與路線圖邊界的「研究重現與版本」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for research reproducibility and revisions in paper/roadmap boundaries?","options":["論文與產品宣稱的適用範圍必然相同。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","並排比較論文摘要與商業宣稱所需新增證據。"],"optionsEn":["A paper and product announcement necessarily support identical scope.","Equal case averages rule out spatial, temporal and model errors.","Compare paper-supported claims with evidence still required for commercial claims."],"answer":2,"explanation":"原始論文的適用範圍可能小於公司路線圖；應保存版本、數據與推論限制。 並排比較論文摘要與商業宣稱所需新增證據。","explanationEn":"A paper may support narrower claims than a roadmap; retain versions, data and inference limitations. Compare paper-supported claims with evidence still required for commercial claims."}}]}],"summary":"以近接材料、奇偶讀出及拓撲宣稱審查解析Majorana 1 研發與奇偶量測證據：六個原理與架構單元、十二項可保存的分析及驗證作業，附假想量化例、來源及衍生工程比較。","summaryEn":"Explore Majorana 1 research and parity-measurement evidence through proximity materials, parity readout and review of topological claims: six principle/architecture units and twelve saved analysis/validation tasks, with an assumed numerical example, primary sources and related engineering comparisons.","scope":"依公開研究與裝置資料編寫的離線模型、編譯及證據判讀。不是實機組裝、雷射或低溫作業SOP；假想算例不代表廠商精度、量子優勢或容錯能力。研發宣稱與已驗證觀測分開標示。","scopeEn":"Offline models, compilation and evidence interpretation from public research/device sources. Not hardware assembly, laser/cryogenic SOPs; assumed examples are not vendor fidelity, advantage or fault tolerance. Development claims and demonstrated observations remain distinct.","workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"假想讀出1000次，兩標籤各500次，錯分各5次與10次：兩類錯分率1%與2%，均衡錯分率1.5%。這只能量化該假想讀出，不能證明拓撲性、非阿貝爾操作或受保護邏輯位元。","textEn":"Assume 1000 readouts with 500 per label and 5/10 misassignments: class errors 1%/2%, balanced error 1.5%. This quantifies assumed readout only, not topology, non-Abelian operations or protected logical qubits.","assumptions":"數值是本課自行設定的假設，不代表實機量測、產品額定或操作參數；改變模型邊界後必須重算。","assumptionsEn":"Inputs are independently selected assumptions, not measured hardware, ratings or operating parameters; recalculate after boundary changes.","sourceScope":"原創數值練習；來源支援公開架構及領域原理，不宣稱來源提供這組假想數據。","sourceScopeEn":"Original numerical exercise; sources support public architecture and principles, not these assumed measurements."},"diagram":{"type":"network","labels":["InAs–Al近接結構","電容與奇偶干涉","指派分佈","平庸態競爭假說","受保護操作證據","論文與路線圖邊界"],"labelsEn":["InAs-Al proximity structures","Capacitance and parity interference","Assignment distributions","Trivial-state competing hypotheses","Protected-operation evidence","Paper/roadmap boundaries"],"original":true,"notToScale":true},"vendorHints":[{"name":"Microsoft research authors / Nature","nameEn":"Microsoft research authors / Nature","url":"https://www.nature.com/articles/s41586-024-08445-2","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-parity"]},{"name":"Microsoft","nameEn":"Microsoft","url":"https://quantum.microsoft.com/en-us/insights/blogs/microsoft-unveils-majorana-1-worlds-first-quantum-processor-powered-by-topological-qubits","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-majoranaclaim"]}],"architectureNodes":[["近接材料裝置","Proximity-material device"],["奇偶干涉計","Parity interferometer"],["電容讀出","Capacitance readout"],["推論模型","Inference models"],["證據比較","Evidence comparison"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,4]],"architectureFamily":"qpu","educationEdition":11,"enrichmentVersion":11}};
